from copy import deepcopy
from datetime import datetime
import sqlite3
import unittest

import config
import database
import training_verification


NOW = datetime(2026, 11, 15, 12)
CHECKED_AT = '2026-11-15 10:00:00'


class TrainingVerificationTests(unittest.TestCase):
    """Keep occurrence evidence separate from forecasts, bookability and course descriptions."""

    def setUp(self):
        """Create a sparse-ID project fixture with a private archive and one projected event."""
        self.connection = database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        database.init_db(self.connection)
        with self.connection:
            self.connection.execute('''INSERT INTO directions (id,key,name,sort_order)
                VALUES (3,'sports','Sports',1)''')
            self.connection.execute('''INSERT INTO bundles
                (id,key,direction_id,name,is_other,sort_order)
                VALUES (5,'sports_other',3,'Other',1,1)''')
            self.connection.execute('''INSERT INTO training_imports
                (id,file_name,source_fingerprint,imported_at)
                VALUES (8,'fixture.csv','fixture-hash','2026-11-15 09:00:00')''')
            self.connection.execute('''INSERT INTO training_history
                (id,import_id,source_row,sport,variant,weekday_text,start_time,date_original,
                 training_date,participants_signed_up,participants_teacher,max_participants)
                VALUES (1,8,2,'Tennis','Level 1','Montag','07:00','Montag, 2. November 2026',
                        '2026-11-02',0,3,9999)''')
        self.add_course()

    def add_course(self, external_id='history-pattern:1', series_id=17, event_id=42,
                   start='2026-11-16 07:00:00', end='2026-11-16 08:30:00', estimated=1,
                   provenance=True):
        """Add a private synthetic pattern, avoiding any real uploaded course text."""
        with self.connection:
            self.connection.execute('''INSERT INTO series
                (id,source,external_id,title,bundle_id,sport,level,location_type,description)
                VALUES (?,'unisport',?,'Private draft title',5,'Tennis','','tba',
                        'Private estimate; not a public course description')''',
                (series_id, external_id))
            self.connection.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status)
                VALUES (?,?,?,?,?,'unknown')''', (event_id, series_id, start, end, estimated))
            if provenance:
                self.connection.execute('''INSERT INTO event_provenance
                    (event_id,kind,forecast_anchor_date,evidence_weeks,created_at)
                    VALUES (?,'projected','2026-11-06',3,'2026-11-15 09:00:00')''', (event_id,))

    def raw(self, appointment_id=501, product_id=66, title='Tennis - Level 1',
            description=None, start='2026-11-16T06:00:00.000Z',
            end='2026-11-16T06:59:00.000Z'):
        """Build one public API occurrence with its actual UTC start and inclusive end."""
        return {'id': appointment_id, 'linkedProductId': product_id,
                'linkedProduct': {'id': product_id, 'description': title},
                'description': description, 'startDate': start, 'endDate': end}

    def snapshot(self, records=None, checked_at=CHECKED_AT):
        """Wrap raw public records in a complete bounded endpoint response."""
        records = [self.raw()] if records is None else records
        query = ('?startDateMin=2026-11-16&startDateMax=2026-11-22'
                 '&showBookingsFull=true&showCourses=true')
        return {'source_url': config.UNISPORT_SCHEDULE_API_URL + query,
                'checked_at': checked_at,
                'payload': {'data': records, 'count': len(records), 'total': len(records),
                            'page': 1, 'pageCount': 1}}

    def approval(self, external_id='history-pattern:1', product_id=66,
                 public_title='Tennis - Level 1', description=''):
        """Explicitly approve one pattern-to-public-course mapping, including its variant."""
        return {'external_id': external_id, 'product_id': product_id,
                'public_title': public_title, 'appointment_description': description}

    def verify(self, snapshots=None, approvals=None):
        """Run the public verifier at a fixed Zurich clock without network access."""
        snapshots = [self.snapshot()] if snapshots is None else snapshots
        approvals = [self.approval()] if approvals is None else approvals
        return training_verification.verify_training_events(
            self.connection, snapshots, approvals, now=NOW)

    def state(self):
        """Capture all relevant SQL values using fixed statements, never dynamic table SQL."""
        queries = ['SELECT * FROM series ORDER BY id', 'SELECT * FROM events ORDER BY id',
                   'SELECT * FROM event_provenance ORDER BY event_id',
                   'SELECT * FROM training_imports ORDER BY id',
                   'SELECT * FROM training_history ORDER BY id',
                   'SELECT * FROM users ORDER BY id', 'SELECT * FROM interactions ORDER BY id',
                   'SELECT * FROM invitations ORDER BY id']
        return [[tuple(row) for row in self.connection.execute(query).fetchall()]
                for query in queries]

    def row(self, query, params=()):
        """Read one row through bound values for concise semantic assertions."""
        return self.connection.execute(query, params).fetchone()

    def test_exact_occurrence_updates_end_and_preserves_forecast_evidence(self):
        """Use the public inclusive end while retaining identity, archive and unknown access."""
        before = self.state()
        report = self.verify()
        self.assertEqual(report['n_updated'], 1)
        self.assertEqual(report['n_observations'], 1)
        event = self.row('SELECT * FROM events WHERE id=?', (42,))
        self.assertEqual(event['series_id'], 17)
        self.assertEqual(event['start_time'], '2026-11-16 07:00:00')
        self.assertEqual(event['end_time'], '2026-11-16 08:00:00')
        self.assertEqual(event['end_is_estimated'], 0)
        self.assertEqual(event['status'], 'unknown')
        origin = self.row('SELECT * FROM event_provenance WHERE event_id=?', (42,))
        self.assertEqual(origin['kind'], 'website')
        self.assertEqual(origin['forecast_anchor_date'], '2026-11-06')
        self.assertEqual(origin['evidence_weeks'], 3)
        self.assertEqual(origin['created_at'], '2026-11-15 09:00:00')
        self.assertTrue(origin['verification_url'].startswith('https://'))
        self.assertEqual(origin['verified_at'], CHECKED_AT)
        after = self.state()
        for index in (0, 3, 4, 5, 6, 7):
            self.assertEqual(after[index], before[index])
        self.assertEqual(self.row('PRAGMA integrity_check')[0], 'ok')
        self.assertEqual(self.connection.execute('PRAGMA foreign_key_check').fetchall(), [])

    def test_repeating_same_evidence_is_idempotent(self):
        """A repeated snapshot retains all SQL values and counts the existing verified slot."""
        self.verify()
        before = self.state()
        report = self.verify()
        self.assertEqual(report['n_updated'], 0)
        self.assertEqual(report['n_existing'], 1)
        self.assertEqual(self.state(), before)

    def test_one_public_date_does_not_promote_siblings_or_import_unreviewed_fields(self):
        """Proof applies to one date; prices and participant details never enter public fields."""
        with self.connection:
            self.connection.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status)
                VALUES (900,17,'2026-11-23 07:00:00','2026-11-23 08:30:00',1,'unknown')''')
            self.connection.execute('''INSERT INTO event_provenance
                (event_id,kind,forecast_anchor_date,evidence_weeks,created_at)
                VALUES (900,'projected','2026-11-06',3,'2026-11-15 09:00:00')''')
        before = self.state()
        record = self.raw()
        record.update(price='25.00', occupancy=0, maxParticipants=20,
                      participants=[{'name': 'Synthetic participant'}])
        record['linkedProduct'].update(price='25.00', supervisor='Synthetic supervisor')
        report = self.verify(snapshots=[self.snapshot([record])])
        self.assertEqual(report['n_updated'], 1)
        self.assertGreaterEqual(report['n_unmatched'], 1)
        after = self.state()
        self.assertEqual(after[0], before[0])
        self.assertEqual(after[1][1], before[1][1])
        self.assertEqual(after[2][1], before[2][1])
        self.assertIsNone(self.row('SELECT price_rappen FROM series WHERE id=17')[0])
        self.assertEqual(self.row('SELECT status FROM events WHERE id=42')[0], 'unknown')

    def test_unrelated_multiday_official_activity_does_not_reject_valid_evidence(self):
        """A legitimate multi-day trip in the response does not block a matching training date."""
        trip = self.raw(601, product_id=99, title='Ski and snowboard trip',
                        start='2026-11-18T06:00:00.000Z',
                        end='2026-11-21T06:59:00.000Z')
        before = self.state()
        report = self.verify(snapshots=[self.snapshot([self.raw(), trip])])
        self.assertEqual(report['n_updated'], 1)
        self.assertEqual(report['n_observations'], 2)
        self.assertEqual(self.row('SELECT kind FROM event_provenance WHERE event_id=42')[0],
                         'website')
        self.assertEqual(self.row('SELECT COUNT(*) FROM events')[0], 1)
        after = self.state()
        for index in (0, 3, 4, 5, 6, 7):
            self.assertEqual(after[index], before[index])

    def test_next_monday_rows_outside_requested_week_are_ignored(self):
        """A backend spillover row cannot verify a forecast outside the requested date range."""
        with self.connection:
            self.connection.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status)
                VALUES (900,17,'2026-11-23 07:00:00','2026-11-23 08:30:00',1,'unknown')''')
            self.connection.execute('''INSERT INTO event_provenance
                (event_id,kind,forecast_anchor_date,evidence_weeks,created_at)
                VALUES (900,'projected','2026-11-06',3,'2026-11-15 09:00:00')''')
        before = self.state()
        spillover = self.raw(502, start='2026-11-23T06:00:00.000Z',
                             end='2026-11-23T06:59:00.000Z')
        report = self.verify(snapshots=[self.snapshot([self.raw(), spillover])])
        self.assertEqual(report['n_updated'], 1)
        self.assertEqual(report['n_observations'], 1)
        self.assertGreaterEqual(report['n_unmatched'], 1)
        after = self.state()
        self.assertEqual(after[1][1], before[1][1])
        self.assertEqual(after[2][1], before[2][1])
        self.assertEqual(self.row('SELECT kind FROM event_provenance WHERE event_id=42')[0],
                         'website')

    def test_unapproved_pattern_and_nonmatching_exact_date_are_untouched(self):
        """No approval or only another week's public date never verifies a local guess."""
        before = self.state()
        report = self.verify(approvals=[])
        self.assertEqual(report['n_unreviewed'], 1)
        self.assertEqual(self.state(), before)
        other = self.raw(start='2026-11-17T06:00:00.000Z',
                         end='2026-11-17T06:59:00.000Z')
        report = self.verify(snapshots=[self.snapshot([other])])
        self.assertEqual(report['n_updated'], 0)
        self.assertGreaterEqual(report['n_unmatched'], 1)
        self.assertEqual(self.state(), before)

    def test_product_and_title_must_both_match_the_reviewed_mapping(self):
        """Another product or different public title cannot inherit an approved pattern."""
        before = self.state()
        wrong = [self.raw(product_id=67), self.raw(title='Tennis - Level 2')]
        for record in wrong:
            with self.subTest(record=record):
                report = self.verify(snapshots=[self.snapshot([record])])
                self.assertEqual(report['n_updated'], 0)
                self.assertEqual(self.state(), before)

    def test_empty_description_is_exact_and_never_a_wildcard(self):
        """A blank approved variant cannot match a named public appointment description."""
        record = self.raw(description='Level 2 only')
        before = self.state()
        report = self.verify(snapshots=[self.snapshot([record])])
        self.assertEqual(report['n_updated'], 0)
        self.assertEqual(self.state(), before)
        approved = self.approval(description='  LEVEL 2 ONLY  ')
        report = self.verify(snapshots=[self.snapshot([record])], approvals=[approved])
        self.assertEqual(report['n_updated'], 1)

    def test_duplicate_snapshots_do_not_create_additional_occurrences(self):
        """The same official appointment ID from duplicate responses is one observation."""
        snapshot = self.snapshot()
        report = self.verify(snapshots=[snapshot, deepcopy(snapshot)])
        self.assertEqual(report['n_updated'], 1)
        self.assertEqual(report['n_observations'], 1)
        self.assertEqual(self.row('SELECT COUNT(*) FROM events')[0], 1)

    def test_conflicting_duplicate_appointment_id_rejects_the_entire_batch(self):
        """One official ID with different dates, identity or duration cannot be trusted."""
        before = self.state()
        for change in ({'linkedProductId': 67}, {'description': 'Other session'},
                       {'startDate': '2026-11-16T06:15:00.000Z'},
                       {'endDate': '2026-11-16T07:59:00.000Z'}):
            second = self.raw()
            second.update(change)
            with self.subTest(change=change), self.assertRaises(ValueError):
                self.verify(snapshots=[self.snapshot(), self.snapshot([second])])
            self.assertEqual(self.state(), before)

    def test_one_local_slot_with_two_official_candidates_remains_ambiguous(self):
        """Distinct official IDs sharing the approved date and time need explicit review."""
        before = self.state()
        report = self.verify(snapshots=[self.snapshot([self.raw(), self.raw(502)])])
        self.assertEqual(report['n_updated'], 0)
        self.assertGreaterEqual(report['n_ambiguous'], 1)
        self.assertEqual(self.state(), before)

    def test_one_official_appointment_cannot_verify_two_local_patterns(self):
        """Two approved historical patterns competing for one occurrence both stay private."""
        self.add_course(external_id='history-pattern:2', series_id=18, event_id=900)
        before = self.state()
        report = self.verify(approvals=[self.approval(), self.approval('history-pattern:2')])
        self.assertEqual(report['n_updated'], 0)
        self.assertGreaterEqual(report['n_ambiguous'], 1)
        self.assertEqual(self.state(), before)

    def test_legacy_slot_without_provenance_is_protected(self):
        """Matching public text never retroactively claims a legacy event's origin."""
        with self.connection:
            self.connection.execute('DELETE FROM event_provenance WHERE event_id=?', (42,))
        before = self.state()
        report = self.verify()
        self.assertEqual(report['n_updated'], 0)
        self.assertGreaterEqual(report['n_protected'], 1)
        self.assertEqual(self.state(), before)

    def test_conflicting_known_duration_is_protected(self):
        """An independently corrected duration is not overwritten by another end time."""
        with self.connection:
            self.connection.execute('''UPDATE events SET end_is_estimated=0,end_time=?
                WHERE id=?''', ('2026-11-16 08:15:00', 42))
        before = self.state()
        report = self.verify()
        self.assertEqual(report['n_updated'], 0)
        self.assertGreaterEqual(report['n_protected'], 1)
        self.assertEqual(self.state(), before)

    def test_older_website_evidence_cannot_downgrade_a_checked_occurrence(self):
        """An older snapshot leaves the more recent website check and its values intact."""
        self.verify()
        before = self.state()
        report = self.verify(snapshots=[self.snapshot(checked_at='2026-11-15 09:30:00')])
        self.assertEqual(report['n_updated'], 0)
        self.assertEqual(self.state(), before)

    def test_invalid_snapshots_fail_before_any_mutation(self):
        """Incomplete pages, foreign URLs, invalid clocks and unsafe dates are rejected."""
        before = self.state()
        changes = [('payload', 'total', 2), ('payload', 'count', 2),
                   ('payload', 'page', 2), ('payload', 'pageCount', 2),
                   (None, 'source_url', 'https://example.org/public-schedule'),
                   (None, 'checked_at', '2026-11-16 10:00:00'),
                   (None, 'checked_at', 'invalid')]
        for parent, key, value in changes:
            broken = self.snapshot()
            target = broken if parent is None else broken[parent]
            target[key] = value
            with self.subTest(field=key, value=value), self.assertRaises(ValueError):
                self.verify(snapshots=[self.snapshot(), broken])
            self.assertEqual(self.state(), before)
        for change in ({'startDate': '2026-11-16T06:00:00'},
                       {'endDate': '2026-11-16T05:59:00.000Z'}, {'id': 0},
                       {'linkedProduct': {'id': 67, 'description': 'Tennis - Level 1'}}):
            record = self.raw()
            record.update(change)
            with self.subTest(change=change), self.assertRaises(ValueError):
                self.verify(snapshots=[self.snapshot([record])])
            self.assertEqual(self.state(), before)

    def test_pending_caller_transaction_is_rejected_without_committing_it(self):
        """Website validation cannot commit or roll back somebody else's active work."""
        before = self.state()
        self.connection.execute('UPDATE series SET description=? WHERE id=?', ('Pending', 17))
        with self.assertRaises(ValueError):
            self.verify()
        self.assertTrue(self.connection.in_transaction)
        self.assertEqual(self.row('SELECT description FROM series WHERE id=17')[0], 'Pending')
        self.connection.rollback()
        self.assertEqual(self.state(), before)

    def test_provenance_failure_rolls_back_every_event_and_retains_user_references(self):
        """A failure after an earlier update leaves the whole batch and private archive intact."""
        self.add_course(external_id='history-pattern:2', series_id=18, event_id=900,
                        start='2026-11-17 07:00:00', end='2026-11-17 08:30:00')
        with self.connection:
            self.connection.executemany('''INSERT INTO users
                (id,display_name,friend_code,is_synthetic,created_at) VALUES (?,?,?,0,?)''',
                [(23, 'Test A', 'TESTA1', CHECKED_AT), (77, 'Test B', 'TESTB1', CHECKED_AT)])
            self.connection.execute('''INSERT INTO interactions
                (id,user_id,event_id,status,confirmed_at) VALUES (301,23,42,'confirmed',?)''',
                (CHECKED_AT,))
            self.connection.execute('''INSERT INTO invitations
                (id,sender_id,recipient_id,event_id,status,created_at)
                VALUES (902,23,77,900,'pending',?)''', (CHECKED_AT,))
            self.connection.execute('''CREATE TRIGGER reject_second_verification
                BEFORE UPDATE ON event_provenance WHEN NEW.event_id=900
                BEGIN SELECT RAISE(ABORT,'forced verification failure'); END''')
        records = [self.raw(), self.raw(502, product_id=67, title='Tennis - Level 2',
                   start='2026-11-17T06:00:00.000Z', end='2026-11-17T06:59:00.000Z')]
        approvals = [self.approval(), self.approval('history-pattern:2', 67, 'Tennis - Level 2')]
        before = self.state()
        with self.assertRaises(sqlite3.IntegrityError):
            self.verify(snapshots=[self.snapshot(records)], approvals=approvals)
        self.assertFalse(self.connection.in_transaction)
        self.assertEqual(self.state(), before)
        self.assertEqual(self.connection.execute('PRAGMA foreign_key_check').fetchall(), [])
